import{_ as t,o as i,c as o,ag as n}from"./chunks/framework.BpFM782D.js";const m=JSON.parse('{"title":"doc-consistency","description":"","frontmatter":{},"headers":[],"relativePath":"en/skills/doc-consistency.md","filePath":"en/skills/doc-consistency.md"}'),r={name:"en/skills/doc-consistency.md"};function d(c,e,a,l,s,h){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="doc-consistency" tabindex="-1">doc-consistency <a class="header-anchor" href="#doc-consistency" aria-label="Permalink to &quot;doc-consistency&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Name</td><td>doc-consistency</td></tr><tr><td>Description</td><td>Documentation consistency guard. Auto-triggers when modifying blueprint, architecture, or IA-related files to ensure related documents stay in sync and versions increment correctly.</td></tr><tr><td>Source Directory</td><td><code>skills/doc-consistency/</code></td></tr></tbody></table><hr><h1 id="documentation-consistency-skill" tabindex="-1">Documentation Consistency Skill <a class="header-anchor" href="#documentation-consistency-skill" aria-label="Permalink to &quot;Documentation Consistency Skill&quot;">​</a></h1><p>Automatically triggered when documentation or specifications are modified, ensuring all related documents remain consistent.</p><h2 id="trigger" tabindex="-1">Trigger <a class="header-anchor" href="#trigger" aria-label="Permalink to &quot;Trigger&quot;">​</a></h2><p>Automatically triggered when files in the following directories are modified:</p><ul><li><code>blueprint/information-architecture/</code></li><li><code>blueprint/architecture/</code></li><li><code>blueprint/design-system/</code></li><li><code>blueprint/archive/</code></li><li><code>docs/</code></li></ul><p>If the project does not have a <code>blueprint/</code> directory structure, this skill does not apply.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><h3 id="rule-1-information-architecture-file-sync" tabindex="-1">Rule 1: Information Architecture file sync <a class="header-anchor" href="#rule-1-information-architecture-file-sync" aria-label="Permalink to &quot;Rule 1: Information Architecture file sync&quot;">​</a></h3><p>When any file in the IA directory is modified, check and sync related files:</p><table tabindex="0"><thead><tr><th>Modified file</th><th>Must check</th></tr></thead><tbody><tr><td><code>routes.md</code></td><td><code>navigation.md</code>, <code>sitemap.md</code></td></tr><tr><td><code>navigation.md</code></td><td><code>routes.md</code>, <code>sitemap.md</code></td></tr><tr><td><code>sitemap.md</code></td><td><code>routes.md</code>, <code>navigation.md</code>, <code>page-inventory.md</code></td></tr><tr><td><code>page-inventory.md</code></td><td><code>sitemap.md</code></td></tr></tbody></table><p><strong>Action</strong>: Read related files and confirm consistency. If inconsistencies are found, proactively flag and fix them.</p><p>These files cross-reference each other; updating routes without updating navigation is the most common oversight. This lookup table means you don&#39;t have to rely on memory — change one file and you know exactly which others to check.</p><h3 id="rule-2-versioned-document-incrementing" tabindex="-1">Rule 2: Versioned document incrementing <a class="header-anchor" href="#rule-2-versioned-document-incrementing" aria-label="Permalink to &quot;Rule 2: Versioned document incrementing&quot;">​</a></h3><p>When modifying architecture decisions or implementation plans, follow the version increment process:</p><ol><li>Create a new version in <code>archive/</code> (<code>tech-decisions-vN+1.md</code> or <code>implementation-plan-vN+1.md</code>)</li><li>Sync the summary to <code>architecture/overview.md</code></li><li>Update version references in <code>README.md</code></li><li>Update all files that reference the old version</li></ol><p><strong>Prohibited</strong>:</p><ul><li>Overwriting existing version files directly (history is lost; decision evolution becomes untraceable)</li><li>Updating only the overview without creating an archive version (violates the traceability principle)</li></ul><h3 id="rule-3-read-blueprint-before-modifying" tabindex="-1">Rule 3: Read blueprint before modifying <a class="header-anchor" href="#rule-3-read-blueprint-before-modifying" aria-label="Permalink to &quot;Rule 3: Read blueprint before modifying&quot;">​</a></h3><p>Before modifying any blueprint-related file:</p><ol><li>First read <code>architecture/overview.md</code> to understand the big picture</li><li>Confirm the modification does not conflict with existing architectural decisions</li><li>If an architectural decision needs to change, create a new version first (Rule 2)</li></ol><h2 id="checklist" tabindex="-1">Checklist <a class="header-anchor" href="#checklist" aria-label="Permalink to &quot;Checklist&quot;">​</a></h2><p>After completing documentation changes, confirm:</p><ul><li>[ ] Related IA files have been synced (Rule 1)</li><li>[ ] Versioned documents have been correctly incremented (Rule 2)</li><li>[ ] Modification is consistent with <code>architecture/overview.md</code> (Rule 3)</li><li>[ ] No orphaned references (pointing to files or versions that no longer exist)</li></ul><h2 id="integration" tabindex="-1">Integration <a class="header-anchor" href="#integration" aria-label="Permalink to &quot;Integration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Integration</th><th>Description</th></tr></thead><tbody><tr><td>Preceding</td><td>Step 1 of the <code>feature-kickoff</code> skill (read blueprint)</td></tr><tr><td>Parallel</td><td>Independent of Phase 2 of the <code>quality-gate</code> skill (security scan)</td></tr><tr><td>Following</td><td><code>git-workflow</code> skill (tag commit as <code>docs:</code> or <code>chore:</code>)</td></tr></tbody></table>',28)])])}const f=t(r,[["render",d]]);export{m as __pageData,f as default};
